def _user_data_dir():
    """The program's folder in the user's home. The folder used under the old name is renamed, so nothing is lost."""
    home = os.path.expanduser("~")
    new, old = os.path.join(home, "MCP_XA_Energy"), os.path.join(home, "MOT_XA_Energy")
    try:
        if os.path.isdir(old) and not os.path.exists(new):
            os.rename(old, new)
    except Exception:
        pass
    return new


def _app_data_file(name):
    base = getattr(sys, "_MEIPASS", None) or os.path.dirname(os.path.abspath(sys.executable if FROZEN else __file__))
    return os.path.join(base, name)


def app_version():
    """Version of this installed program as numbers, e.g. (1, 0, 1). () when running from the .py file."""
    try:
        with open(_app_data_file("version.txt"), encoding="utf-8") as f:
            return tuple(int(x) for x in re.findall(r"\d+", f.read()))
    except Exception:
        return ()


def vtext(v):
    return ".".join(str(x) for x in v) if v else "-"


def gh_repo_name():
    try:    # the repository the installer was built for (a public releases repository: no token needed)
        with open(_app_data_file("app_config.json"), encoding="utf-8") as f:
            r = str(json.load(f).get("repo", "")).strip()
            if r:
                return r
    except Exception:
        pass
    return (SETTINGS.get("gh_repo") or "").strip() or "MoutonBU/mot-xa-energy-releases"


GH_API = "https://api.github.com"


class _NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, *a, **k):
        return None


def gh_latest_release(repo, token, timeout=15):
    """The newest release of a (private) repository: {'ver', 'tag', 'name', 'asset_id', 'size', 'notes'}. Raises RuntimeError with a plain message."""
    if not repo:
        raise RuntimeError("No update source is set.")
    req = urllib.request.Request(GH_API + "/repos/%s/releases/latest" % repo,
                                 headers={"Accept": "application/vnd.github+json", "User-Agent": "MCP-XA-Energy",
                                          **({"Authorization": "Bearer " + token} if token else {})})
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            d = json.loads(r.read().decode("utf-8"))
    except urllib.error.HTTPError as ex:
        if ex.code in (401, 403):
            raise RuntimeError("The update server refused the request. Try again later.")
        if ex.code == 404:
            raise RuntimeError("No update has been published yet.")
        raise RuntimeError("GitHub answered %s." % ex.code)
    except Exception as ex:
        raise RuntimeError("Could not reach GitHub: %s" % ex)
    m_ = tuple(int(x) for x in re.findall(r"\d+", str(d.get("tag_name", ""))))
    assets = [a for a in d.get("assets", []) if str(a.get("name", "")).lower().endswith("_setup.exe")]
    if not m_ or not assets:
        raise RuntimeError("The latest release has no installer file.")
    a = assets[0]
    return {"ver": m_, "tag": d.get("tag_name", ""), "name": a["name"], "asset_id": a["id"], "size": a.get("size", 0),
            "notes": (d.get("body") or "").strip()}


def gh_download_asset(repo, token, asset_id, dest, progress=None, timeout=60):
    """Download a release file of a private repository. The signed link GitHub redirects to must not receive the token."""
    hdr = {"Accept": "application/octet-stream", "User-Agent": "MCP-XA-Energy", **({"Authorization": "Bearer " + token} if token else {})}
    url = GH_API + "/repos/%s/releases/assets/%s" % (repo, asset_id)
    op = urllib.request.build_opener(_NoRedirect)
    try:
        resp = op.open(urllib.request.Request(url, headers=hdr), timeout=timeout)
    except urllib.error.HTTPError as ex:
        if ex.code in (301, 302, 303, 307, 308) and ex.headers.get("Location"):
            resp = urllib.request.urlopen(urllib.request.Request(ex.headers["Location"], headers={"User-Agent": "MCP-XA-Energy"}), timeout=timeout)
        else:
            raise RuntimeError("Download refused (%s)." % ex.code)
    total = int(resp.headers.get("Content-Length") or 0)
    got = 0
    with open(dest, "wb") as f:
        while True:
            b = resp.read(1 << 20)
            if not b:
                break
            f.write(b)
            got += len(b)
            if progress:
                if progress(got, total) is False:
                    raise RuntimeError("Cancelled.")
    resp.close()
    return dest


class _GhThread(QThread):
    """Runs one GitHub call off the screen thread. kind 'check' -> result dict or error text; 'download' -> file path or error text."""
    done = Signal(object, str)
    prog = Signal(int, int)

    def __init__(self, kind, repo, token, asset_id=0, dest="", parent=None):
        super().__init__(parent)
        self.kind, self.repo, self.token, self.asset_id, self.dest = kind, repo, token, asset_id, dest
        self.stop = False

    def run(self):
        try:
            if self.kind == "check":
                self.done.emit(gh_latest_release(self.repo, self.token), "")
            else:
                gh_download_asset(self.repo, self.token, self.asset_id, self.dest,
                                  lambda g, t: (self.prog.emit(g, t), not self.stop)[1])
                self.done.emit(self.dest, "")
        except Exception as ex:
            self.done.emit(None, str(ex))


