def _icon_for(text):
    t = (text or "").lower().replace("&", "&")
    for k, n in ICON_KEYS:
        if k in t:
            return n
    return None


def decorate_icons(root, force=False):
    """Give every button / menu entry under root an icon, chosen from its text."""
    from PySide6.QtWidgets import QPushButton as _PB, QTableWidget as _TW, QMenu as _MN
    for b in root.findChildren(_PB):
        if (not force and not b.icon().isNull()) or not b.text():
            continue
        par, in_table = b.parent(), False
        while par is not None:
            if isinstance(par, _TW):
                in_table = True
                break
            par = par.parent()
        if in_table:
            continue
        n = _icon_for(b.text())
        if n:
            b.setIcon(make_icon(n, "#ffffff" if b.property("accent") else "#eceef0", 18))
            b.setIconSize(QSize(18, 18))
    if isinstance(root, _MN):
        for a in root.actions():
            if (force or a.icon().isNull()) and a.text():
                n = _icon_for(a.text())
                if n:
                    a.setIcon(make_icon(n, "#eceef0", 16))


from flow_layout import FlowLayout


def _nopix(lb):
    try:
        pm = lb.pixmap()
        return pm is None or pm.isNull()
    except Exception:
        return True


def wrap_long_labels(root):
    """A long one-line label sets the whole window's minimum width (the window then opens far wider than the screen).
    Letting such labels wrap keeps the window the size it was given."""
    for lb in root.findChildren(QLabel):
        try:
            if not lb.wordWrap() and len(lb.text()) > 60 and _nopix(lb):
                lb.setWordWrap(True)
        except Exception:
            pass


class _IconFilter(QObject):
    """Adds icons to dialogs and menus the moment they appear."""

    _POLISH, _SHOW = QEvent.Type.Polish, QEvent.Type.Show

    def eventFilter(self, obj, ev):
        t_ = ev.type()
        if t_ is not self._POLISH and t_ is not self._SHOW:     # nearly every event: leave at once
            return False
        if t_ is self._POLISH and isinstance(obj, QLabel):
            try:
                if not obj.wordWrap() and len(obj.text()) > 60 and _nopix(obj):
                    obj.setWordWrap(True)
            except Exception:
                pass
        if t_ is self._SHOW and isinstance(obj, (QDialog, QMenu)):
            try:
                if not obj.property("_icons_done") or isinstance(obj, QMenu):
                    decorate_icons(obj)
                    obj.setProperty("_icons_done", True)
            except Exception:
                pass
        return False


def apply_icons(win, force=False):
    """Tab icons, button icons and big icons on the home cards."""
    mt = getattr(win, "main_tabs", None)
    if mt is not None:
        for i, n in enumerate(("home", "lightvent", "bolt", "building", "ruler")):
            if i < mt.count():
                mt.setTabIcon(i, make_icon(n, "#eceef0", 18))
        mt.setIconSize(QSize(18, 18))
    st = getattr(win, "tabs", None)
    if st is not None:
        for i, n in enumerate(("window", "door", "room", "results", "plan")):
            if i < st.count():
                st.setTabIcon(i, make_icon(n, "#eceef0", 17))
        st.setIconSize(QSize(17, 17))
    decorate_icons(win, force)


