HW_SOLAR_PKG = {150: ("SOL-150-DIR", 1, 2.0, "SOL-PANEL-2B", 2), 200: ("SOL-200-DIR", 1, 2.5, "SOL-PANEL-2.5", 2),
                300: ("SOL-300-DIR", 2, 2.0, "SOL-PANEL-2B", 3)}     # code, panels in the package, m2 per panel, panel model, element kW


