    PROV_LAT = {"Western Cape": 33.5, "Eastern Cape": 32.5, "Northern Cape": 29.5, "Free State": 28.5,
                "KwaZulu-Natal": 29.0, "North West": 26.5, "Gauteng": 26.0, "Mpumalanga": 25.5, "Limpopo": 23.5,
                "Southern Cape": 34.0}

    def _xa_autolat(self):
        """Fill the latitude from the chosen town (or the middle of its province) unless the user typed one."""
        if getattr(self, "_lat_manual", False) or not hasattr(self, "xa_lat"):
            return
        t = self.xa_town.currentText()
        lat = None
        if t in ZA_MAP_DATA["towns"]:
            lat = -ZA_MAP_DATA["towns"][t][0]
        else:
            lat = self.PROV_LAT.get(self.xa_prov.currentText())
        if lat is not None:
            self.xa_lat.setText(f"{lat:.1f}")

    def _xa_latitude(self):
        try:
            return abs(float(self.xa_lat.text().replace(",", ".")))
        except ValueError:
            return self.PROV_LAT.get(self.xa_prov.currentText(), 30.0)

    def _weather_dir(self):
        d = os.path.join(_user_data_dir(), "weather")
        os.makedirs(d, exist_ok=True)
        return d

    def _set_weather(self, w, path):
        import math as _m
        self.weather = w
        self.rd["epw"] = path
        la, lo = self._site_lonlat()
        km = 111.0 * (((w["lat"] - la) ** 2 + ((w["lon"] - lo) * _m.cos(_m.radians(la))) ** 2) ** 0.5)
        msg = (f"Weather data: {w['name'] or 'weather file'} ({w['lat']:.2f}, {w['lon']:.2f}), "
               f"{km:.0f} km from the site. Mean temperature {float(w['T'].mean()):.1f} \u00b0C.")
        if km > 100:
            msg += " This file is far from your site: pick a nearer one if you can."
        if hasattr(self, "wx_lbl"):
            self.wx_lbl.setText(msg)

    def fetch_weather(self):
        la, lo = self._site_lonlat()
        QApplication.setOverrideCursor(Qt.WaitCursor)
        try:
            txt = fetch_pvgis_epw(la, lo)
            w = parse_epw(txt)
            w["source"] = "EU PVGIS typical meteorological year 2005-2020 (satellite and reanalysis data for the exact point, not a weather station)"
            path = os.path.join(self._weather_dir(), f"pvgis_{la:.3f}_{lo:.3f}.epw")
            with open(path, "w", encoding="utf-8") as f:
                f.write(txt)
        except Exception as ex:
            QApplication.restoreOverrideCursor()
            QMessageBox.warning(self, APP_NAME, "The weather data could not be downloaded:\n%s\n\nCheck the internet "
                                "connection, or pick a weather file (.epw) of your own instead." % ex)
            return
        QApplication.restoreOverrideCursor()
        self._set_weather(w, path)
        QMessageBox.information(self, APP_NAME, "Weather data for the site was downloaded and saved (modelled from satellite "
                                "and reanalysis data, not measured at a weather station; for a station file use the .epw "
                                "button):\n%s" % path)

    def load_epw(self):
        path, _ = QFileDialog.getOpenFileName(self, "Weather file", "", "EPW weather file (*.epw);;All files (*)")
        if not path:
            return
        try:
            with open(path, "r", encoding="utf-8", errors="replace") as f:
                w = parse_epw(f.read())
        except Exception as ex:
            QMessageBox.warning(self, APP_NAME, "That weather file could not be read:\n%s" % ex)
            return
        self._set_weather(w, path)

    def _weather_for_report(self):
        w = getattr(self, "weather", None)
        if w is None and self.rd.get("epw") and os.path.exists(self.rd["epw"]):
            try:
                with open(self.rd["epw"], "r", encoding="utf-8", errors="replace") as f:
                    w = parse_epw(f.read())
                self.weather = w
            except Exception:
                w = None
        return w

    def import_kml(self):
        path, _ = QFileDialog.getOpenFileName(self, "Site location - KML or KMZ file", "",
                                              "Google Earth files (*.kml *.kmz);;All files (*)")
        if not path:
            return
        try:
            marks = read_kml(path)
        except Exception as ex:
            QMessageBox.warning(self, APP_NAME, f"That file could not be read as KML / KMZ:\n{ex}")
            return
        if not marks:
            QMessageBox.information(self, APP_NAME, "No place, line or plot outline was found in that file.")
            return
        marks.sort(key=lambda m_: {"Polygon": 0, "Point": 1, "Line": 2}[m_["kind"]])
        pick = marks[0]
        if len(marks) > 1:
            labels = [f"{m_['name']}  ({m_['kind'].lower()}, {len(m_['pts'])} point{'s' if len(m_['pts']) != 1 else ''})"
                      for m_ in marks]
            lab, ok = QInputDialog.getItem(self, APP_NAME, "Which one is your site? (the plot outline is best)",
                                           labels, 0, False)
            if not ok:
                return
            pick = marks[labels.index(lab)]
        pts = pick["pts"]
        lon = sum(q[0] for q in pts) / len(pts)
        lat = sum(q[1] for q in pts) / len(pts)
        # latitude + nearest listed town
        self._lat_manual = True
        self._coord_src = "Google Earth KML"
        self.xa_lat.setText(f"{abs(lat):.4f}")
        self.rd["lon"] = f"{lon:.5f}"
        zm = self.zone_map
        pt = zm._xy(lon, lat)
        near = zm.nearby(pt)
        msg = [f"Site: {pick['name']}.  Latitude {abs(lat):.4f}\u00b0 {'S' if lat < 0 else 'N'}, longitude {lon:.4f}\u00b0."]
        if near:
            town, km = near[0]
            zm.click_ll = (lon, lat)
            zm.near_list = near
            zm.click_km = max(near[-1][1], 40.0)
            self._zone_map_picked(zm.town_pv.get(town) or self.xa_prov.currentText(), town)
            zm.zoom_to(lon, lat, 4.0)
            msg.append(f"Nearest listed town: {town.rstrip(' *')} ({km:.0f} km), energy zone {XA_TOWNS.get(town, '?')}. "
                       "Check it in step 2 if your town is closer to another listed one.")
        msg.append("The latitude is used for the shading depth (SANS 10400-XA table 3).")
        # north from the outline
        ifc_path = getattr(self, "ifc_path", "")
        if pick["kind"] == "Polygon" and ifc_path and os.path.exists(ifc_path):
            QApplication.setOverrideCursor(Qt.WaitCursor)
            try:
                model = ifc_site_outline(ifc_path)
                site_xy, _la, _lo = kml_to_metres(pts)
                cands = north_candidates(model, site_xy) if len(model) >= 3 else []
            except Exception:
                cands = []
            finally:
                QApplication.restoreOverrideCursor()
            if cands:
                dlg = KmlNorthDialog(self, site_xy, model, cands,
                                     (self.ifc_data or {}).get("north") if isinstance(self.ifc_data, dict) else None)
                if dlg.exec() == QDialog.DialogCode.Accepted and dlg.angle is not None:
                    self.xa_north.setText("%g" % dlg.angle)
                    self._north_src = "kml"
                    msg.append(f"North on the plan set to {dlg.angle:g}\u00b0 from the plot outline. The Rooms table "
                               "and the orientation check now use it.")
                else:
                    msg.append("North was not changed.")
            else:
                msg.append("The building outline could not be matched to the plot, so north was not changed.")
        elif pick["kind"] == "Polygon":
            msg.append("To work out north from the plot outline, import your IFC model first (Home or Energy XA) "
                       "and then import this KML file again.")
        else:
            msg.append("This file has only a point, so north cannot be worked out from it. Use a KML with the plot "
                       "outline (a polygon), or set the north angle yourself.")
        self._xa_refresh()
        msg.append("Next, press 'Get weather data for this site' to load the climate of this exact location.")
        QMessageBox.information(self, APP_NAME, "\n\n".join(msg))

    def _zone_pick_province(self, name):
        self._zone_nearby = None
        self.zone_map.click_ll = None
        self.xa_prov.setCurrentText(name)

    def _zone_map_picked(self, pv, town):
        near = self.zone_map.near_list
        tp = self.zone_map.town_pv
        self._zone_nearby = near
        inpv = next((t for t, _km in near if tp.get(t) == pv), town)
        self.xa_prov.setCurrentText(pv)
        self._zone_sync_force = True
        if inpv:
            self.xa_town.setCurrentText(inpv)
        self._zone_guide_sync()

    def _zone_item_clicked(self, it):
        t = it.data(Qt.UserRole) or it.text()
        pv = self.zone_map.town_pv.get(t) or next((k for k, v in XA_PROVINCES.items() if t in v), "")
        if pv and pv != self.xa_prov.currentText():
            keep = self._zone_nearby
            self.xa_prov.setCurrentText(pv)
            self._zone_nearby = keep
        self.xa_town.setCurrentText(t)

    def _zone_guide_sync(self):
        if not hasattr(self, "zone_card") or getattr(self, "_zone_busy", False):
            return
        self._zone_busy = True
        try:
            pv = self.xa_prov.currentText()
            for n, b in self._zone_btns.items():
                b.blockSignals(True)
                b.setChecked(n == pv)
                b.blockSignals(False)
            names = XA_REGIONS.get(pv, [])
            cur = self.xa_town.currentText()
            self.zone_map.set_state(pv, cur)
            self.zone_towns.blockSignals(True)
            self.zone_towns.clear()
            near = self._zone_nearby if self.zone_map.click_ll else None
            if near:
                self.zone_head.setText("<b>Step 2</b> &nbsp;Pick the exact town (closest to your click)")
                for t, km in near:
                    it = QListWidgetItem(f"{t}     {km:.0f} km")
                    it.setData(Qt.UserRole, t)
                    it.setToolTip(f"Zone {XA_TOWNS.get(t, '?')}")
                    self.zone_towns.addItem(it)
                    if t == cur:
                        self.zone_towns.setCurrentItem(it)
            else:
                self.zone_head.setText("<b>Step 2</b> &nbsp;Pick the nearest town")
                if not names:
                    self.zone_towns.addItem("Click the map to see the towns near that spot")
                    self.zone_towns.item(0).setFlags(Qt.NoItemFlags)
                for t in names:
                    it = QListWidgetItem(t)
                    it.setData(Qt.UserRole, t)
                    self.zone_towns.addItem(it)
                    if t == cur:
                        self.zone_towns.setCurrentItem(it)
            self.zone_towns.blockSignals(False)
            z = self.xa_zone.currentText()
            nm = self.ZONE_NAMES.get(z, "")
            if cur in XA_TOWNS:
                head = f"<span style='font-size:15pt'><b>Energy zone {z}</b></span> &nbsp;{nm}"
                body = xa_town_note(cur)
            else:
                head = f"<span style='font-size:15pt'><b>Energy zone {z}</b></span> &nbsp;{nm}"
                body = ("No town picked yet, so this is the zone currently set. Choose the nearest town above. "
                        "If your town is not listed, pick the closest one, or set the zone yourself below.")
            self.zone_card.setText(head + "<br><span style='color:rgba(255,255,255,170)'>" + body
                                   + " The zone decides the minimum insulation (R-values) and glazing limits used in the report.</span>")
        finally:
            self._zone_busy = False

    # ---------------- Detail Notes tab (work in progress) ----------------
    def _build_detail_tab(self):
        """Detailmakker inside the suite: opens a DWG/DXF of a construction detail, writes the callout notes and saves
        the noted drawing. It is built the first time the tab is opened, so the rest of the program starts as fast as before."""
        page = QWidget()
        self._det_lay = QVBoxLayout(page)
        self._det_lay.setContentsMargins(0, 0, 0, 0)
        self._det_win = None
        self.main_tabs.addTab(page, "Detail Notes (WIP)")
        self.main_tabs.currentChanged.connect(lambda i: self._detail_open() if self.main_tabs.widget(i) is page else None)

    def _detail_open(self):
        if self._det_win is not None:
            return
        QApplication.setOverrideCursor(Qt.CursorShape.WaitCursor)
        try:
            import mot_detail_notes_app as dn
            dn.LIGHT[0] = bool(light())
            w = dn.Win(embedded=True)
            w.setWindowFlags(Qt.WindowType.Widget)
            w.make_icon, w.is_light = make_icon, light
            w.setStyleSheet(dn.QSS)
            def _xa_info():
                z = self.xa_zone.currentText()
                t = self.xa_town.currentText()
                return {"zone": z, "roof": XA_ROOF_R.get(z), "heavy": XA_HEAVY_WALL_R.get(z), "light": XA_LIGHT_WALL_R.get(z),
                        "town": t if t in XA_TOWNS else ""}
            def _xa_set_town(t):
                t = (t or "").strip()
                if t not in XA_TOWNS:
                    return False
                pv = next((k for k, v_ in XA_PROVINCES.items() if t in v_), None)
                if pv and pv in XA_REGIONS:
                    self.xa_prov.setCurrentText(pv)
                self.xa_town.setCurrentText(t)          # also sets the energy zone, same as picking it on the Energy tab
                return True
            w.xa_provider = _xa_info
            w.xa_set_town = _xa_set_town
            w.xa_towns = sorted(XA_TOWNS)
            self.xa_zone.currentTextChanged.connect(lambda _z: w.xa_resync())   # zone changed on the Energy tab: notes follow
            w.xa_sync_ui()
            self._det_lay.addWidget(w)
            self._det_win = w
            try:
                w.update_theme()
            except Exception:
                pass
        except Exception as ex:
            lb = QLabel("The Detail Notes tool could not start:\n%s\n\nIt needs the ezdxf and matplotlib packages." % ex)
            lb.setWordWrap(True)
            self._det_lay.addWidget(lb)
            self._det_win = lb
        finally:
            QApplication.restoreOverrideCursor()

    # ---------------- Coverage and FAR tab ----------------
    def _build_cov_tab(self):
        page = QWidget()
        lay = QVBoxLayout(page)
        lay.setContentsMargins(10, 10, 10, 10)
        top = QHBoxLayout()
        self.cov_stand = QDoubleSpinBox(); self.cov_stand.setRange(0, 10_000_000); self.cov_stand.setDecimals(2)
        self.cov_stand.setSuffix(" m2"); self.cov_stand.setMinimumWidth(140)
        self.cov_maxcov = QDoubleSpinBox(); self.cov_maxcov.setRange(0, 100); self.cov_maxcov.setDecimals(1)
        self.cov_maxcov.setSuffix(" %"); self.cov_maxcov.setSpecialValueText("no limit")
        self.cov_maxfar = QDoubleSpinBox(); self.cov_maxfar.setRange(0, 20); self.cov_maxfar.setDecimals(2)
        self.cov_maxfar.setSpecialValueText("no limit")
        for lab, wdg in (("Stand (erf) area:", self.cov_stand), ("Maximum coverage:", self.cov_maxcov),
                         ("Maximum FAR:", self.cov_maxfar)):
            top.addWidget(QLabel(lab)); top.addWidget(wdg); top.addSpacing(14)
        self.cov_walls = QDoubleSpinBox(); self.cov_walls.setRange(0, 60); self.cov_walls.setDecimals(1)
        self.cov_walls.setSuffix(" %"); self.cov_walls.setValue(15.0)
        self.cov_walls.setToolTip("Rooms are net areas. This adds the thickness of the walls to get the gross floor "
                                  "area and footprint. Set it to 0 if your room areas already include the walls.")
        self.cov_basis = QComboBox()
        self.cov_basis.addItems(["Net room areas + wall allowance", "IFC gross floor area (from the model)",
                                 "Gross floor area typed in Building details (Energy XA)"])
        self.cov_basis.setToolTip("Where the floor areas come from.\n1: the room areas on the Rooms tab (net) plus the wall "
                                  "allowance.\n2: the gross area the IFC gives for its rooms (GrossFloorArea).\n3: the "
                                  "whole-building gross floor area typed on the Energy XA tab.\nOptions 2 and 3 are shared "
                                  "over the levels in proportion to their room areas.")
        top.addWidget(QLabel("Areas from:")); top.addWidget(self.cov_basis); top.addSpacing(10)
        top.addWidget(QLabel("Add for walls:")); top.addWidget(self.cov_walls)
        top.addStretch()
        lay.addLayout(top)
        fill = QHBoxLayout()
        bf = QPushButton("Fill the blocks from the Rooms list")
        bf.setToolTip("Adds up the rooms on the Rooms tab per level: the footprint is the biggest level, "
                      "the floor area is all levels together. Add your other blocks by hand.")
        bf.clicked.connect(lambda: self.cov_fill_from_rooms(True))
        fill.addWidget(bf)
        self.cov_lvl = QLabel("")
        self.cov_lvl.setWordWrap(True)
        fill.addWidget(self.cov_lvl, 1)
        lay.addLayout(fill)
        info = QLabel("Coverage = footprint of the buildings (plus the roofs you tick) / stand area.  "
                      "FAR (floor area ratio) = total floor area of all storeys / stand area.  "
                      "Floor area left empty = footprint x storeys.  Use the limits from the zoning scheme / title deed.")
        info.setWordWrap(True)
        lay.addWidget(info)
        self.cov_blocks = QTableWidget(0, 5)
        self.cov_blocks.setHorizontalHeaderLabels(["Block", "Footprint m2 (coverage)", "Storeys",
                                                   "Floor area m2 (all storeys, optional)", "Count"])
        self.cov_roofs = QTableWidget(0, 3)
        self.cov_roofs.setHorizontalHeaderLabels(["Carport / roof", "Roof area m2", "Count in coverage"])
        for t_, h_ in ((self.cov_blocks, 170), (self.cov_roofs, 130)):
            t_.horizontalHeader().setStretchLastSection(True)
            t_.horizontalHeader().setSectionResizeMode(0, QHeaderView.ResizeMode.Stretch)
            t_.setMinimumHeight(h_)
            t_.verticalHeader().setDefaultSectionSize(36)
            t_.itemChanged.connect(lambda *_: self._cov_refresh())
        for lab, t_, add_, ph in (("Blocks (buildings)", self.cov_blocks, self._cov_add_block, "Add block"),
                                  ("Carports and other roofs (optional extra for the coverage)", self.cov_roofs,
                                   self._cov_add_roof, "Add carport / roof")):
            hl = QHBoxLayout()
            hl.addWidget(QLabel(f"<b>{lab}</b>")); hl.addStretch()
            b1 = QPushButton(ph); b1.clicked.connect(lambda _=False, f=add_: f())
            if t_ is self.cov_blocks:
                bi_ = QPushButton("Add block from IFC...")
                bi_.setToolTip("Reads one more block from its own IFC file: its levels, storeys and floor areas. "
                               "Uses the 'Areas from' choice above (net rooms + wall allowance, or the IFC gross floor area).")
                bi_.clicked.connect(self._cov_add_block_from_ifc)
                hl.addWidget(bi_)
            b2 = QPushButton("Remove selected")
            b2.clicked.connect(lambda _=False, t=t_: (t.removeRow(t.currentRow()) if t.currentRow() >= 0 else None,
                                                      self._cov_refresh()))
            hl.addWidget(b1); hl.addWidget(b2)
            lay.addLayout(hl)
            lay.addWidget(t_)
        self.cov_result = QLabel("")
        self.cov_result.setWordWrap(True)
        self.cov_result.setTextFormat(Qt.TextFormat.RichText)
        lay.addWidget(self.cov_result)
        bot = QHBoxLayout()
        bp = QPushButton("Preview coverage and FAR report")
        bp.clicked.connect(lambda: self.preview_pdf_report(self._write_cov_pdf, lambda: None))
        be = QPushButton("Export report...")
        be.clicked.connect(self.export_cov_pdf)
        bs = QPushButton("Export each calculation as its own PDF...")
        bs.clicked.connect(lambda: self.export_subject_pdfs("cov"))
        bsp = QPushButton("Site plan sheets (one per block + all blocks)...")
        bsp.setToolTip("Small PDFs with no cover page: one for each block and one for all the blocks together, cut to the size of "
                       "their content so they can be placed on the site plan.")
        bsp.clicked.connect(self.export_cov_sheets)
        for b_ in (bp, be, bs, bsp):
            bot.addWidget(b_)
        bot.addStretch()
        lay.addLayout(bot)
        for sp in (self.cov_stand, self.cov_maxcov, self.cov_maxfar):
            sp.valueChanged.connect(lambda *_: self._cov_refresh())
        self.cov_walls.valueChanged.connect(lambda *_: self.cov_fill_from_rooms(False, "walls"))
        self.cov_basis.currentIndexChanged.connect(lambda *_: (self.cov_walls.setEnabled(self.cov_basis.currentIndex() == 0),
                                                                self.cov_fill_from_rooms(True)))
        self.main_tabs.currentChanged.connect(lambda i: self.cov_fill_from_rooms(False)
                                              if self.main_tabs.widget(i) is self.cov_page else None)
        self._cov_busy = False
        self.cov_page = page
        self.main_tabs.addTab(page, "Coverage && FAR")
        self._cov_add_block(); self._cov_refresh()

    def cov_fill_from_rooms(self, force=False, mode="tab"):
        """Fill the blocks and carport roofs from the Rooms list: always on the button, when the wall allowance
        changes (if the blocks came from the rooms), and when the tab is opened while the table is still empty."""
        if getattr(self, "_cov_busy", True):
            return
        st = self.cov_state()
        if not force:
            if mode == "walls" and not any(b.get("levels") for b in st["blocks"]):
                return
            if mode == "tab" and any(cov_num(b["fp"]) > 0 for b in st["blocks"]):
                return
        try:
            rooms = self.read_rooms()
        except Exception:
            rooms = []
        _nm = os.path.splitext(os.path.basename(getattr(self, "ifc_path", "") or ""))[0]
        _nm = re.sub(r"(?i)^.*?(block\s*\w+).*$", r"\1", _nm).strip() if re.search(r"(?i)block\s*\w+", _nm) else ""
        bi = self.cov_basis.currentIndex()
        total = None
        if bi == 1:
            total = cov_num((getattr(self, "ifc_data", None) or {}).get("gross", 0))
        elif bi == 2:
            total = cov_num(self.xa_gross.text()) if hasattr(self, "xa_gross") else 0.0
        if bi and not total:
            if force:
                QMessageBox.information(self, APP_NAME, "That area is not available (" + (
                    "no IFC is loaded or it has no gross floor areas" if bi == 1 else
                    "type the gross floor area under Building details on the Energy XA tab") +
                    "). The net room areas plus the wall allowance are used instead.")
            total = None
        blocks, roofs = cov_from_rooms(rooms, self.cov_walls.value(), _nm or "Block A", total)
        # the room table has no level names: take the levels from the IFC rooms instead
        ifr = (getattr(self, "ifc_data", None) or {}).get("rooms") or []
        if blocks and blocks[0]["storeys"] <= 1 and len({(r.get("floor") or "") for r in ifr}) > 1:
            class _R:
                def __init__(s_, d):
                    s_.name, s_.area_m2, s_.floor, s_.unit = d.get("name", ""), d.get("area", 0), d.get("floor", ""), ""
            blocks, roofs2 = cov_from_rooms([_R(d) for d in ifr], self.cov_walls.value(), _nm or "Block A", total)
            roofs = roofs or roofs2
        if not blocks:
            if force:
                QMessageBox.information(self, APP_NAME, "There are no rooms yet. Load the IFC or add the rooms on the "
                                        "Light && Ventilation > Rooms tab first, or type the areas in by hand.")
            return
        old_on = {b["name"]: b["on"] for b in st["blocks"]}
        old_roof_on = {r["name"]: r["on"] for r in st["roofs"]}
        self._cov_busy = True
        self.cov_blocks.setRowCount(0)
        self.cov_roofs.setRowCount(0)
        self._cov_busy = False
        for b in blocks:
            self._cov_add_block(b["name"], b["fp"], b["storeys"], b["floor"], old_on.get(b["name"], True), b["levels"])
        for r in roofs:
            self._cov_add_roof(r["name"], r["area"], old_roof_on.get(r["name"], r["on"]))
        self._cov_refresh()

    def _cov_add_block(self, name=None, fp="", storeys=1, floor="", on=True, levels=None):
        t = self.cov_blocks
        self._cov_busy = True
        r = t.rowCount(); t.insertRow(r)
        vals = [name if name is not None else f"Block {chr(65 + r % 26)}", str(fp), str(storeys), str(floor)]
        for c, v in enumerate(vals):
            t.setItem(r, c, QTableWidgetItem(v))
        if levels:
            t.item(r, 0).setData(Qt.ItemDataRole.UserRole, levels)
            t.item(r, 0).setToolTip("Net room area on each level plus the wall allowance:\n" +
                                    "\n".join(f"{n}: {a:.2f} m2" for n, a in levels))
        ck = QTableWidgetItem(); ck.setFlags(Qt.ItemFlag.ItemIsUserCheckable | Qt.ItemFlag.ItemIsEnabled)
        ck.setCheckState(Qt.CheckState.Checked if on else Qt.CheckState.Unchecked)
        t.setItem(r, 4, ck)
        self._cov_busy = False
        self._cov_refresh()

    def _cov_add_block_from_ifc(self):
        """Add one more block (a row) from another IFC file, keeping the blocks already in the table."""
        fn, _ = QFileDialog.getOpenFileName(self, "Choose the IFC of this block", "", "IFC files (*.ifc *.ifczip)")
        if not fn:
            return
        QApplication.setOverrideCursor(Qt.CursorShape.WaitCursor)
        try:
            data = read_ifc_model(fn)
        except Exception as ex:
            QApplication.restoreOverrideCursor()
            QMessageBox.warning(self, APP_NAME, "That IFC could not be read:\n%s" % ex)
            return
        QApplication.restoreOverrideCursor()
        ifr = data.get("rooms") or []

        class _R:
            def __init__(s_, d):
                s_.name, s_.area_m2, s_.floor, s_.unit = d.get("name", ""), d.get("area", 0), d.get("floor", ""), ""
        nm = os.path.splitext(os.path.basename(fn))[0]
        total = cov_num(data.get("gross", 0)) if self.cov_basis.currentIndex() == 1 else None
        blocks, roofs = cov_from_rooms([_R(d) for d in ifr], self.cov_walls.value(), nm, total or None)
        if not blocks:
            QMessageBox.information(self, APP_NAME, "That IFC has no rooms with areas. Add the block by hand with Add block.")
            return
        for b in blocks:
            self._cov_add_block(b["name"], b["fp"], b["storeys"], b["floor"], True, b["levels"])
        for r in roofs:
            self._cov_add_roof(r["name"], r["area"], r["on"])
        self._cov_refresh()

    def _cov_add_roof(self, name=None, area="", on=True):
        t = self.cov_roofs
        self._cov_busy = True
        r = t.rowCount(); t.insertRow(r)
        t.setItem(r, 0, QTableWidgetItem(name if name is not None else f"Carport {r + 1}"))
        t.setItem(r, 1, QTableWidgetItem(str(area)))
        ck = QTableWidgetItem(); ck.setFlags(Qt.ItemFlag.ItemIsUserCheckable | Qt.ItemFlag.ItemIsEnabled)
        ck.setCheckState(Qt.CheckState.Checked if on else Qt.CheckState.Unchecked)
        t.setItem(r, 2, ck)
        self._cov_busy = False
        self._cov_refresh()

    def cov_state(self):
        def tx(t, r, c):
            it = t.item(r, c)
            return it.text().strip() if it else ""

        def on(t, r, c):
            it = t.item(r, c)
            return bool(it and it.checkState() == Qt.CheckState.Checked)
        return {"basis": self.cov_basis.currentIndex(), "walls": self.cov_walls.value(), "stand": self.cov_stand.value(), "max_cov": self.cov_maxcov.value(), "max_far": self.cov_maxfar.value(),
                "blocks": [{"name": tx(self.cov_blocks, r, 0), "fp": tx(self.cov_blocks, r, 1),
                            "storeys": tx(self.cov_blocks, r, 2), "floor": tx(self.cov_blocks, r, 3),
                            "on": on(self.cov_blocks, r, 4),
                            "levels": (self.cov_blocks.item(r, 0).data(Qt.ItemDataRole.UserRole) or []) if self.cov_blocks.item(r, 0) else []}
                           for r in range(self.cov_blocks.rowCount())],
                "roofs": [{"name": tx(self.cov_roofs, r, 0), "area": tx(self.cov_roofs, r, 1),
                           "on": on(self.cov_roofs, r, 2)} for r in range(self.cov_roofs.rowCount())]}

    def cov_load(self, st):
        st = st or {}
        self._cov_busy = True
        self.cov_walls.setValue(cov_num(st.get("walls", 15)) if "walls" in st else 15.0)
        self.cov_basis.blockSignals(True)
        self.cov_basis.setCurrentIndex(int(cov_num(st.get("basis", 0))))
        self.cov_basis.blockSignals(False)
        self.cov_walls.setEnabled(self.cov_basis.currentIndex() == 0)
        self.cov_stand.setValue(cov_num(st.get("stand", 0)))
        self.cov_maxcov.setValue(cov_num(st.get("max_cov", 0)))
        self.cov_maxfar.setValue(cov_num(st.get("max_far", 0)))
        self.cov_blocks.setRowCount(0)
        self.cov_roofs.setRowCount(0)
        self._cov_busy = False
        for b in st.get("blocks", []):
            self._cov_add_block(b.get("name", ""), b.get("fp", ""), b.get("storeys", 1), b.get("floor", ""), b.get("on", True),
                                b.get("levels") or None)
        for r in st.get("roofs", []):
            self._cov_add_roof(r.get("name", ""), r.get("area", ""), r.get("on", True))
        if not st.get("blocks"):
            self._cov_add_block()
        self._cov_refresh()

    def _cov_refresh(self):
        if getattr(self, "_cov_busy", True) or not hasattr(self, "cov_result"):
            return
        _st = self.cov_state()
        self.cov_lvl.setText("   ".join(f"{b['name']}: " + ", ".join(f"{n} {a:.1f} m2" for n, a in b["levels"]) +
                                        f"  ({len(b['levels'])} storeys)" for b in _st["blocks"] if b.get("levels")))
        sc = cov_scenarios(_st)
        if not sc or sc[0]["stand"] <= 0:
            self.cov_result.setText("<i>Enter the stand area and the block footprints to see the coverage and FAR.</i>")
            return
        rows = []
        for r in sc:
            def lim(ok, val, mx, fmt):
                col = "#1B9F4B" if ok else "#E03050"
                return (f"<td align='right'><b style='color:{col}'>{fmt % val}</b>"
                        + (f" <span style='color:#999'>/ {fmt % mx}</span>" if mx > 0 else "") + "</td>")
            rows.append(f"<tr><td>{r['name']}</td><td align='right'>{r['foot'] + r['roof']:.2f}</td>"
                        f"<td align='right'>{r['floor']:.2f}</td>"
                        + lim(r["cov_ok"], r["cov"], r["max_cov"], "%.2f%%") + lim(r["far_ok"], r["far"], r["max_far"], "%.3f")
                        + "</tr>")
        self.cov_result.setText(
            "<table cellspacing='0' cellpadding='4' width='100%'><tr><th align='left'>Calculation</th>"
            "<th align='right'>Covered m2</th><th align='right'>Floor area m2</th>"
            "<th align='right'>Coverage</th><th align='right'>FAR</th></tr>" + "".join(rows) + "</table>")

    def _write_cov_pdf(self, path, only=None, list_only=False):
        import datetime, html as _h
        from PySide6.QtGui import QPdfWriter, QPageSize, QPageLayout, QTextDocument, QFont
        from PySide6.QtCore import QMarginsF, QSizeF, QUrl
        e = lambda x: _h.escape(str(x))
        RED, DARK, GREY = "#C8102E", "#DCDCDC", "#F4F4F4"
        st = self.cov_state()
        scen = cov_scenarios(st)
        if list_only:
            return [r["name"] for r in scen]
        if only:
            scen = [r for r in scen if r["name"] == only]

        def cell(txt, align="left", color=None, bold=False, bg=None):
            sty = f"padding:3px; text-align:{align}; vertical-align:middle;" + (f"color:{color};" if color else "") + \
                  ("font-weight:bold;" if bold else "")
            return f'<td{" bgcolor=" + chr(34) + bg + chr(34) if bg else ""} style="{sty}">{e(txt)}</td>'

        def table(head, rows, widths):
            h = "".join(f'<th bgcolor="{DARK}" width="{widths[i]}%" style="padding:4px;">{e(x)}</th>' for i, x in enumerate(head))
            return (f'<table width="100%" cellspacing="0" cellpadding="0" border="0.6" style="border-color:#bbbbbb; '
                    f'font-size:8.5pt;"><tr>{h}</tr>' + "".join("<tr>" + "".join(r) + "</tr>" for r in rows) + "</table>")

        def verdict(ok, limit):
            if limit <= 0:
                return cell("NO LIMIT SET", "center", "#555555", True, bg="#EDEDED")
            return cell("WITHIN LIMIT" if ok else "EXCEEDS LIMIT", "center", "#1B7F3B" if ok else RED, True,
                        bg="#E7F5EB" if ok else "#FCE8EB")
        head = (f'<table width="100%" cellspacing="0" cellpadding="8" border="0"><tr><td bgcolor="{DARK}" width="9%">'
                f'<img src="logo" height="46"></td><td bgcolor="{DARK}" style="color:#111111;">'
                f'<span style="font-size:17pt; font-weight:bold;">Coverage and Floor Area Ratio</span><br>'
                f'<span style="font-size:9pt; color:#444444;">Stand area {st["stand"]:.2f} m2 &nbsp;|&nbsp; '
                f'{datetime.date.today().strftime("%d %B %Y")}</span></td></tr></table>'
                f'<table width="100%" cellspacing="0" cellpadding="0" border="0"><tr><td bgcolor="{RED}" height="3"></td></tr></table>'
                f'{self._project_info_html()}')
        frags = [head]
        frags.append(f'<p style="font-size:8.5pt; color:#444444;">Coverage = footprint of the buildings'
                     f'{" and carport roofs" if any("carport" in r["name"] for r in scen) else ""} / stand area. '
                     f'FAR = total floor area of all storeys / stand area. Limits used: coverage '
                     f'{(str(round(cov_num(st["max_cov"]), 1)) + "%") if cov_num(st["max_cov"]) > 0 else "none set"}, FAR '
                     f'{round(cov_num(st["max_far"]), 2) if cov_num(st["max_far"]) > 0 else "none set"}.</p>')
        _bn = ["net room areas from the Rooms list plus a " + f"{cov_num(st.get('walls', 15)):g}% wall allowance",
               "the gross floor area given by the IFC model", "the gross floor area typed in Building details"][int(cov_num(st.get("basis", 0))) % 3]
        frags.append(f'<p style="font-size:8pt; color:#555555;">Floor areas taken from: {e(_bn)}. The footprint is the largest level.</p>')
        blocks_by_name = {(b.get("name") or "").strip() or f"Block {i}": b for i, b in enumerate(st["blocks"], 1)}
        for r in scen:
            frags.append(f'<p style="font-size:12pt; font-weight:bold; color:{RED}; margin-left:10px; margin-top:12px;">{e(r["name"])}</p>')
            rows = []
            for bn in r["blocks"]:
                b = blocks_by_name.get(bn, {})
                rows.append([cell(bn, bold=True), cell(f"{cov_num(b.get('fp')):.2f}", "right"),
                             cell(f"{cov_num(b.get('storeys', 1)):g}", "center"),
                             cell(f"{cov_block_floor(b):.2f}", "right")])
                for ln, la in (b.get("levels") or []):
                    rows.append([cell(f"      {ln}", color="#555555"), cell(""), cell(""),
                                 cell(f"{la:.2f}", "right", "#555555")])
            rows.append([cell("Total buildings", "right", bold=True), cell(f"{r['foot']:.2f}", "right", bold=True), cell(""),
                         cell(f"{r['floor']:.2f}", "right", bold=True)])
            frags.append(table(["Block", "Footprint m2", "Storeys", "Floor area m2"], rows, [40, 20, 15, 25]))
            if r["roofs"]:
                rr = [[cell(x.get("name", ""), bold=True), cell(f"{cov_num(x.get('area')):.2f}", "right")]
                      for x in st["roofs"] if x.get("on", True) and x.get("name", "") in r["roofs"]]
                rr.append([cell("Total carport / roof area", "right", bold=True), cell(f"{r['roof']:.2f}", "right", bold=True)])
                frags.append('<p style="font-size:9pt; font-weight:bold; margin-left:10px; margin-top:8px;">Carports and other roofs counted in the coverage</p>')
                frags.append(table(["Roof", "Area m2"], rr, [70, 30]))
            res = [[cell("Stand area", bold=True), cell(f"{r['stand']:.2f} m2", "right"), cell(""), cell("")],
                   [cell("Coverage", bold=True),
                    cell(f"({r['foot']:.2f} + {r['roof']:.2f}) / {r['stand']:.2f} = {r['cov']:.2f}%" if r["roof"] else
                         f"{r['foot']:.2f} / {r['stand']:.2f} = {r['cov']:.2f}%", "right"),
                    cell(f"{r['max_cov']:.1f}%" if r["max_cov"] > 0 else "-", "right"), verdict(r["cov_ok"], r["max_cov"])],
                   [cell("Floor area ratio (FAR)", bold=True), cell(f"{r['floor']:.2f} / {r['stand']:.2f} = {r['far']:.3f}", "right"),
                    cell(f"{r['max_far']:.2f}" if r["max_far"] > 0 else "-", "right"), verdict(r["far_ok"], r["max_far"])]]
            frags.append('<p style="font-size:9pt; font-weight:bold; margin-left:10px; margin-top:8px;">Result</p>')
            frags.append(table(["", "Calculation", "Limit", "Result"], res, [22, 40, 14, 24]))
        frags.append('<p style="font-size:7.5pt; color:#777777; margin-top:14px;">Areas are the figures entered on the Coverage and FAR tab. '
                     'Check the coverage and FAR limits and what the zoning scheme counts (eaves, basements, covered balconies) '
                     f'before submission. Generated by {e(APP_NAME)}.</p>')
        logo = logo_pixmap().toImage().convertToFormat(QImage.Format.Format_ARGB32)
        for yy in range(logo.height()):
            for xx in range(logo.width()):
                c = logo.pixelColor(xx, yy)
                if c.alpha() and c.red() > 200 and c.green() > 200 and c.blue() > 200:
                    logo.setPixelColor(xx, yy, QColor(17, 17, 17, c.alpha()))
        w = QPdfWriter(path)
        w.setPageLayout(QPageLayout(QPageSize(QPageSize.A4), QPageLayout.Orientation.Portrait,
                                    QMarginsF(10, 10, 10, 10), QPageLayout.Unit.Millimeter))
        w.setResolution(96)
        w.setTitle("Coverage and FAR" + (f" - {only}" if only else ""))
        pw, ph = float(w.width()), float(w.height())
        avail = ph - 30.0

        def mkdoc(html_):
            d_ = QTextDocument()
            d_.addResource(QTextDocument.ImageResource, QUrl("logo"), logo)
            d_.setDefaultFont(QFont("Arial", 9))
            d_.setHtml('<html><body style="font-family:Arial; color:#111111;">' + html_ + "</body></html>")
            d_.setPageSize(QSizeF(pw, 1e7))
            return d_
        pages = _pack_pages(mkdoc, frags, avail)
        pages = [(self._report_cover("COVERAGE AND<br>FAR REPORT", "Stand coverage and floor area ratio", only), 0, None)] + list(pages)
        painter = QPainter(w)
        company = self.rd.get("company", "") or APP_NAME
        for i, (html_, y0, y1) in enumerate(pages):
            if i:
                w.newPage()
            painter.save()
            painter.translate(0, -y0)
            if y1 is not None:
                painter.setClipRect(QRectF(-5, y0, pw + 10, y1 - y0 + 1))
            _draw_doc_rounded(painter, mkdoc(html_))
            painter.restore()
            if i == 0:
                continue
            painter.save()
            painter.setPen(QColor("#9A9A9A"))
            painter.setFont(QFont("Arial", 7))
            painter.drawLine(0, int(ph - 24), int(pw), int(ph - 24))
            painter.drawText(QRectF(0, ph - 22, pw * 0.8, 16), int(Qt.AlignmentFlag.AlignLeft),
                             f"{company}  |  {self.rd.get('project') or 'Coverage and FAR'}  |  Coverage and FAR")
            painter.drawText(QRectF(0, ph - 22, pw, 16), int(Qt.AlignmentFlag.AlignRight), f"Page {i + 1} of {len(pages)}")
            painter.restore()
        painter.end()

    def _write_cov_sheet(self, path, only=None, list_only=False):
        """Compact site-plan sheets: one per block (that block's footprint, levels, coverage and FAR on the stand) and one
        for all the blocks together. No cover page and no footer; the page is cut to the size of its content so it can be
        placed straight onto the site plan."""
        import datetime, html as _h
        from PySide6.QtGui import QPdfWriter, QPageSize, QPageLayout, QTextDocument, QFont
        from PySide6.QtCore import QMarginsF, QSizeF, QUrl
        e = lambda x: _h.escape(str(x))
        RED, DARK = "#C8102E", "#DCDCDC"
        st = self.cov_state()
        scen = cov_scenarios(st)
        singles = [r for r in scen if r["name"].startswith("Single block - ")]
        alls = [r for r in scen if r["name"].startswith("All blocks")]
        names = [r["name"] for r in singles] + (["All blocks"] if alls else [])
        if list_only:
            return names
        if only is None:
            only = names[0] if names else None
        if not only:
            return
        blocks_by_name = {(b.get("name") or "").strip() or f"Block {i}": b for i, b in enumerate(st["blocks"], 1)}

        def cell(txt, align="left", color=None, bold=False, bg=None, span=1):
            sty = f"padding:3px 6px; text-align:{align}; vertical-align:middle;" + (f"color:{color};" if color else "") + \
                  ("font-weight:bold;" if bold else "")
            return f'<td{" colspan=" + chr(34) + str(span) + chr(34) if span > 1 else ""}{" bgcolor=" + chr(34) + bg + chr(34) if bg else ""} style="{sty}">{e(txt)}</td>'

        def table(head, rows, widths):
            h = "".join(f'<th bgcolor="{DARK}" width="{widths[i]}%" style="padding:4px 6px;">{e(x)}</th>' for i, x in enumerate(head))
            return (f'<table width="100%" cellspacing="0" cellpadding="0" border="0.6" style="border-color:#bbbbbb; '
                    f'font-size:9pt;"><tr>{h}</tr>' + "".join("<tr>" + "".join(r) + "</tr>" for r in rows) + "</table>")

        def verdict(ok, limit):
            if limit <= 0:
                return cell("no limit set", "center", "#555555", False, bg="#EDEDED")
            return cell("WITHIN LIMIT" if ok else "EXCEEDS LIMIT", "center", "#1B7F3B" if ok else RED, True,
                        bg="#E7F5EB" if ok else "#FCE8EB")

        def results(r, tag=""):
            f = f"{r['foot']:.2f}" + (f" + {r['roof']:.2f}" if r["roof"] else "")
            return [[cell("Coverage" + tag, bold=True), cell(f"({f}) / {r['stand']:.2f} = {r['cov']:.2f}%" if r["roof"] else
                                                               f"{r['foot']:.2f} / {r['stand']:.2f} = {r['cov']:.2f}%", "right"),
                     cell(f"{r['max_cov']:.1f}%" if r["max_cov"] > 0 else "-", "right"), verdict(r["cov_ok"], r["max_cov"])],
                    [cell("FAR" + tag, bold=True), cell(f"{r['floor']:.2f} / {r['stand']:.2f} = {r['far']:.3f}", "right"),
                     cell(f"{r['max_far']:.2f}" if r["max_far"] > 0 else "-", "right"), verdict(r["far_ok"], r["max_far"])]]
        proj = (self.rd.get("project") or "").strip()
        site = (self.rd.get("details") or "").strip()
        sub = " | ".join(x for x in (proj, site, f"Stand {st['stand']:.2f} m2", datetime.date.today().strftime("%d %B %Y")) if x)
        frags = []
        if only == "All blocks":
            title = "ALL BLOCKS - Coverage and FAR"
            rows = []
            r0 = alls[0]
            for bn in r0["blocks"]:
                b = blocks_by_name.get(bn, {})
                rows.append([cell(bn, bold=True), cell(f"{cov_num(b.get('fp')):.2f}", "right"),
                             cell(f"{cov_num(b.get('storeys', 1)):g}", "center"), cell(f"{cov_block_floor(b):.2f}", "right")])
            rows.append([cell("Total buildings", "right", bold=True), cell(f"{r0['foot']:.2f}", "right", bold=True), cell(""),
                         cell(f"{r0['floor']:.2f}", "right", bold=True)])
            frags.append(table(["Block", "Footprint m2", "Storeys", "Floor area m2"], rows, [40, 22, 16, 22]))
            res = [[cell("Stand area", bold=True), cell(f"{r0['stand']:.2f} m2", "right"), cell(""), cell("")]]
            res += results(r0, " (buildings)" if len(alls) > 1 else "")
            if len(alls) > 1:
                rr = alls[1]
                rl = [[cell(x.get("name", ""), bold=True), cell(f"{cov_num(x.get('area')):.2f}", "right")]
                      for x in st["roofs"] if x.get("on", True) and x.get("name", "") in rr["roofs"]]
                rl.append([cell("Carport / roof area counted", "right", bold=True), cell(f"{rr['roof']:.2f}", "right", bold=True)])
                frags.append('<p style="font-size:9pt; font-weight:bold; margin-top:6px; margin-bottom:2px;">Carports and other roofs</p>')
                frags.append(table(["Roof", "Area m2"], rl, [70, 30]))
                res += results(rr, " (with carport roofs)")[:1]
            frags.append('<p style="font-size:9pt; font-weight:bold; margin-top:6px; margin-bottom:2px;">Result</p>')
            frags.append(table(["", "Calculation", "Limit", "Result"], res, [24, 38, 14, 24]))
        else:
            r = next(x for x in singles if x["name"] == only)
            bn = only.replace("Single block - ", "", 1)
            b = blocks_by_name.get(bn, {})
            title = f"{bn.upper()} - Coverage and FAR"
            rows = [[cell("Stand area", bold=True), cell(f"{r['stand']:.2f} m2", "right")],
                    [cell("Footprint (coverage)", bold=True), cell(f"{cov_num(b.get('fp')):.2f} m2", "right")],
                    [cell("Storeys", bold=True), cell(f"{cov_num(b.get('storeys', 1)):g}", "right")]]
            for ln, la in (b.get("levels") or []):
                rows.append([cell(f"      {ln}", color="#555555"), cell(f"{la:.2f} m2", "right", "#555555")])
            rows.append([cell("Floor area (all storeys)", bold=True), cell(f"{cov_block_floor(b):.2f} m2", "right", bold=True)])
            frags.append(table(["", "Area"], rows, [60, 40]))
            frags.append('<p style="font-size:9pt; font-weight:bold; margin-top:6px; margin-bottom:2px;">Result (this block alone on the stand)</p>')
            frags.append(table(["", "Calculation", "Limit", "Result"], results(r), [18, 44, 14, 24]))
        html_ = (f'<table width="100%" cellspacing="0" cellpadding="5" border="0"><tr><td bgcolor="{DARK}" style="color:#111111;">'
                 f'<span style="font-size:13pt; font-weight:bold;">{e(title)}</span><br>'
                 f'<span style="font-size:8pt; color:#444444;">{e(sub)}</span></td></tr></table>'
                 f'<table width="100%" cellspacing="0" cellpadding="0" border="0"><tr><td bgcolor="{RED}" height="2"></td></tr></table>'
                 + "".join(frags) +
                 '<p style="font-size:7pt; color:#777777; margin-top:4px;">Coverage = footprint / stand area. FAR = floor area of all storeys / stand area.</p>')
        W = 600.0                                              # content width in px at 96 dpi (about 159 mm)
        d_ = QTextDocument()
        d_.setDefaultFont(QFont("Arial", 9))
        d_.setHtml('<html><body style="font-family:Arial; color:#111111;">' + html_ + "</body></html>")
        d_.setPageSize(QSizeF(W, 1e7))
        H = float(d_.size().height())
        mm = lambda px: px / 96.0 * 25.4
        w = QPdfWriter(path)
        w.setPageLayout(QPageLayout(QPageSize(QSizeF(mm(W) + 8, mm(H) + 8), QPageSize.Unit.Millimeter), QPageLayout.Orientation.Portrait,
                                    QMarginsF(4, 4, 4, 4), QPageLayout.Unit.Millimeter))
        w.setResolution(96)
        w.setTitle("Coverage and FAR - " + only)
        painter = QPainter(w)
        _draw_doc_rounded(painter, d_)
        painter.end()

    def export_cov_sheets(self):
        """One compact PDF per block and one for all blocks together, ready to place on the site plan."""
        self.export_subject_pdfs("covs")

    def export_cov_pdf(self):
        path, _ = QFileDialog.getSaveFileName(self, "Export coverage and FAR report",
                                              self.pdf_default_path("Coverage and FAR Report"), "PDF (*.pdf)")
        if not path:
            return
        if not path.lower().endswith(".pdf"):
            path += ".pdf"
        self._remember_pdf_dir(path)
        self._write_cov_pdf(path)
        self.toast_saved(path)

    def _build_xa_tab(self):
        from PySide6.QtWidgets import QMenu
        self.xa_elements = []
        self.xa_glass = {}
        self.rd = dict(RD_DEFAULTS)
        self._xa_loading = False
        page = QWidget()
        outer = QVBoxLayout(page)
        scroll = QScrollArea()
        scroll.setWidgetResizable(True)
        inner = QWidget()
        v = QVBoxLayout(inner)
        v.setSpacing(14)
        outer_v = v
        scroll.setWidget(inner)
        outer.addWidget(scroll)

        def heading(txt, sub=""):
            """Start a new framed group (a box with a title) and make it the layout the next widgets go into."""
            nonlocal v
            box = IconGroupBox(txt)
            box.setObjectName("xaGroup")
            vb = QVBoxLayout(box)
            vb.setContentsMargins(14, 8, 14, 12)
            vb.setSpacing(8)
            outer_v.addWidget(box)
            if txt == "Where is the building?":
                self._where_box = box            # moved onto the Home page under Step 1 (see _build_home)
            if txt == "Building details":
                self._details_box = box          # moved onto the Home page under Step 1 (see _build_home)
            if sub:
                lab = QLabel(sub)
                lab.setWordWrap(True)
                lab.setObjectName("xaSub")
                vb.addWidget(lab)
            v = vb

        heading("Where is the building?",
                "Two quick steps: click the province, then pick the nearest town. The energy zone is set for you.")
        v.addWidget(self._make_units_chk())
        self._build_zone_guide(v)
        v.addWidget(QLabel("Or choose from the lists instead:"))
        row = QHBoxLayout()
        row.addWidget(QLabel("Province / region:"))
        self.xa_prov = QComboBox()
        self.xa_prov.setMaxVisibleItems(15)
        self.xa_prov.addItems(["(all provinces)"] + list(XA_REGIONS))
        self.xa_prov.setMinimumWidth(190)
        row.addWidget(self.xa_prov)
        row.addWidget(QLabel("Town:"))
        self.xa_town = QComboBox()
        self.xa_town.setMaxVisibleItems(25)
        self.xa_town.setMinimumWidth(230)
        row.addWidget(self.xa_town)
        row.addWidget(QLabel("Energy zone:"))
        self.xa_zone = QComboBox()
        self.xa_zone.addItems(XA_ZONES)
        self.xa_zone.setCurrentText("1")
        row.addWidget(self.xa_zone)
        row.addStretch()
        v.addLayout(row)
        self.xa_sel = QLabel("")
        self.xa_sel.setVisible(False)   # the zone card above shows this note
        v.addWidget(self.xa_sel)
        self.xa_zone.currentTextChanged.connect(lambda _t: (self._xa_refresh(), self._xa_autofill()))

        def town_changed(t):
            if t in XA_TOWNS:
                self.xa_zone.setCurrentText(XA_TOWNS[t])
                self.xa_sel.setText(xa_town_note(t))
                self.xa_sel.setWordWrap(True)
            else:
                self.xa_sel.setText("Choose a town, or set the energy zone yourself.")
        self.xa_town.currentTextChanged.connect(town_changed)

        def fill_towns(pv, keep=None):
            names = sorted(XA_TOWNS) if pv not in XA_REGIONS else XA_REGIONS[pv]
            cur = keep or self.xa_town.currentText()
            self.xa_town.blockSignals(True)
            self.xa_town.clear()
            self.xa_town.addItems(["(choose)"] + names)
            self.xa_town.setCurrentText(cur if cur in names else "(choose)")
            self.xa_town.blockSignals(False)
            if cur in names:
                town_changed(cur)
        self._xa_fill_towns = fill_towns
        self.xa_prov.currentTextChanged.connect(lambda pv: fill_towns(pv))
        fill_towns("(all provinces)")
        self.xa_prov.activated.connect(lambda _i: (setattr(self, '_zone_nearby', None), setattr(self.zone_map, 'click_ll', None), self._zone_guide_sync()))
        self.xa_prov.currentTextChanged.connect(lambda _p: self._zone_guide_sync())
        self.xa_town.currentTextChanged.connect(lambda _t: self._zone_guide_sync())
        self.xa_town.currentTextChanged.connect(lambda _t: self._xa_autolat())
        self.xa_zone.currentTextChanged.connect(lambda _z: self._zone_guide_sync())
        self._zone_guide_sync()

        heading("Building details", "Occupancy, use, orientation and floor areas for the report.")
        g = QGridLayout()
        self.xa_occ = QComboBox()
        self.xa_occ.setMaxVisibleItems(32)
        self.xa_occ.addItems(XA_OCCUPANCY)
        self.xa_occ.setCurrentText(self.rd["occupancy"])
        self.xa_hrs = QLineEdit()
        self.xa_hrs.setPlaceholderText("e.g. 24")
        self.xa_days = QLineEdit()
        self.xa_days.setPlaceholderText("e.g. 7")
        self.xa_north = QLineEdit()
        self.xa_north.setPlaceholderText("degrees, e.g. 58")
        self.xa_nett = QLabel("-")
        self.xa_total = QLineEdit()
        self.xa_total.setPlaceholderText("m2 (optional)")
        self.xa_gross = QLineEdit()
        self.xa_gross.setPlaceholderText("whole building, all floors (m2) - type it in")
        self.xa_gross.setToolTip("The total area of the whole building, everything included: ground floor, "
                                 "first floor and any other floor. Type it in yourself. The building's maximum "
                                 "energy demand and consumption are worked out from it.")
