        self._hw_store = {}          # {mode index: {group key: {"sys","cyl","col","ppl"}}}
        self._hw_hidden = {}         # {mode index: [group keys the user removed]}
        self._hw_custom = {}         # {mode index: [rows added by hand]}
        self._hw_sel = None
        self._hw_keys = None
        row = QHBoxLayout()
