# ---------------------------------------------------------------- sign-in screen (accounts kept on this PC)
ACCOUNTS_PATH = os.path.join(os.path.dirname(SETTINGS_PATH), "accounts.json")


def _acc_load():
    try:
        with open(ACCOUNTS_PATH, encoding="utf-8") as f:
            d = json.load(f)
            d.setdefault("users", [])
            return d
    except Exception:
        return {"users": []}


def _acc_save(d):
    try:
        os.makedirs(os.path.dirname(ACCOUNTS_PATH), exist_ok=True)
        with open(ACCOUNTS_PATH, "w", encoding="utf-8") as f:
            json.dump(d, f, indent=1)
        return True
    except Exception:
        return False


def _pw_hash(pw, salt_hex):
    import hashlib
    return hashlib.pbkdf2_hmac("sha256", pw.encode("utf-8"), bytes.fromhex(salt_hex), 200000).hex()


def acc_register(name, email, pw):
    """Creates an account. Returns (recovery_key, error). The password itself is never stored, only a salted hash."""
    import secrets
    d = _acc_load()
    em = email.strip().lower()
    if any(u["email"] == em for u in d["users"]):
        return None, "An account with that email already exists. Sign in instead."
    salt, rsalt = secrets.token_hex(16), secrets.token_hex(16)
    rk = "-".join(secrets.token_hex(2).upper() for _ in range(4))
    d["users"].append({"name": name.strip(), "email": em, "salt": salt, "hash": _pw_hash(pw, salt),
                       "rsalt": rsalt, "rhash": _pw_hash(rk, rsalt)})
    if not _acc_save(d):
        return None, "The account could not be saved on this PC."
    return rk, ""


def acc_check(email, pw):
    import hmac
    em = email.strip().lower()
    for u in _acc_load()["users"]:
        if u["email"] == em:
            return u if hmac.compare_digest(_pw_hash(pw, u["salt"]), u["hash"]) else None
    return None


def acc_reset(email, recovery, new_pw):
    import hmac, secrets
    d = _acc_load()
    em = email.strip().lower()
    for u in d["users"]:
        if u["email"] == em and hmac.compare_digest(_pw_hash(recovery.strip().upper(), u["rsalt"]), u["rhash"]):
            u["salt"] = secrets.token_hex(16)
            u["hash"] = _pw_hash(new_pw, u["salt"])
            return _acc_save(d)
    return False


def acc_remember(email):
    import secrets, hashlib
    tok = secrets.token_hex(24)
    d = _acc_load()
    d["remember"] = {"email": email.strip().lower(), "tok": hashlib.sha256(tok.encode()).hexdigest()}
    _acc_save(d)
    SETTINGS["login_token"] = tok
    save_settings()


def acc_forget():
    SETTINGS["sb_refresh"] = ""
    d = _acc_load()
    d.pop("remember", None)
    _acc_save(d)
    SETTINGS["login_token"] = ""
    save_settings()


def acc_remembered():
    """The user who ticked 'Keep me signed in' on this PC, or None."""
    import hashlib
    d = _acc_load()
    r, tok = d.get("remember"), SETTINGS.get("login_token", "")
    if r and tok and hashlib.sha256(tok.encode()).hexdigest() == r.get("tok"):
        for u in d["users"]:
            if u["email"] == r["email"]:
                return u
    return None


# ---------------------------------------------------------------- online accounts (Supabase Auth, kept off this PC)
SB_URL = "https://erfgsisfvttercpytsnq.supabase.co"         # the project URL, e.g. https://abcdxyz.supabase.co   (filled in once the account service is set up)
SB_KEY = "sb_publishable_MzRfcJZToTLiwi_TimtM3A_ukRjN2bj"         # the project's public "anon" key (it is meant to be public; it cannot read or change accounts by itself)
OFFLINE_DAYS = 14   # how long a PC that was signed in before may keep working with no internet


def sb_conf():
    u, k = SB_URL, SB_KEY
    try:
        with open(_app_data_file("app_config.json"), encoding="utf-8") as f:
            c = json.load(f)
            u, k = c.get("sb_url") or u, c.get("sb_key") or k
    except Exception:
        pass
    u = (u or "").strip().rstrip("/")
    return (u, (k or "").strip()) if u and k else None


class SbError(Exception):
    def __init__(self, msg, offline=False, status=0):
        super().__init__(msg)
        self.offline, self.status = offline, status


def _sb(method, path, body=None, token=None, timeout=15):
    u, k = sb_conf()
    hdr = {"apikey": k, "Content-Type": "application/json"}
    if token:                      # the new "publishable" keys are not tokens, so they go in apikey only
        hdr["Authorization"] = "Bearer " + token
    req = urllib.request.Request(u + path, data=json.dumps(body).encode("utf-8") if body is not None else None, headers=hdr, method=method)
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            raw = r.read().decode("utf-8") or "{}"
            return json.loads(raw)
    except urllib.error.HTTPError as ex:
        try:
            d = json.loads(ex.read().decode("utf-8"))
        except Exception:
            d = {}
        msg = d.get("msg") or d.get("error_description") or d.get("message") or d.get("error") or ("HTTP %s" % ex.code)
        raise SbError(str(msg), False, ex.code)
    except Exception as ex:
        raise SbError("No internet connection (%s)" % ex, True)


def sb_licence(token):
    """What the service says about this person's licence: 'ok', 'none' (no key entered yet), 'revoked' or 'expired'."""
    d = _sb("POST", "/rest/v1/rpc/licence_status", {}, token=token)
    st = d.get("state", "none") if isinstance(d, dict) else "none"
    if st == "none":                       # an account without a licence: the service makes one now (no key to type)
        try:
            d = _sb("POST", "/rest/v1/rpc/ensure_my_licence", {}, token=token)
            st = d.get("state", "none") if isinstance(d, dict) else "none"
        except SbError as ex:
            if ex.offline:
                raise
    return st


def sb_redeem(token, key):
    d = _sb("POST", "/rest/v1/rpc/redeem_licence", {"p_key": key.strip()}, token=token)
    return d.get("state", "none") if isinstance(d, dict) else "none"


def _sb_pack(d):
    u = d.get("user") or {}
    return {"name": (u.get("user_metadata") or {}).get("name") or (u.get("email") or ""), "email": u.get("email", ""),
            "status": "?", "refresh": d.get("refresh_token", ""), "token": d.get("access_token", "")}


def sb_login(email, pw):
    return _sb_pack(_sb("POST", "/auth/v1/token?grant_type=password", {"email": email.strip().lower(), "password": pw}))


def sb_refresh(refresh_token):
    return _sb_pack(_sb("POST", "/auth/v1/token?grant_type=refresh_token", {"refresh_token": refresh_token}))


def new_licence_key():
    import secrets
    return "MCP-" + "-".join(secrets.token_hex(2).upper() for _ in range(3))


def sb_signup(name, email, pw, key=""):
    """Creates the account. The licence key is made here and sent along, so the service can e-mail it (from your own mailbox)."""
    _sb("POST", "/auth/v1/signup", {"email": email.strip().lower(), "password": pw,
                                    "data": {"name": name.strip(), "licence_key": key}})


def sb_send_code(email):
    _sb("POST", "/auth/v1/recover", {"email": email.strip().lower()})


def sb_reset(email, code, new_pw):
    d = _sb("POST", "/auth/v1/verify", {"type": "recovery", "email": email.strip().lower(), "token": code.strip()})
    _sb("PUT", "/auth/v1/user", {"password": new_pw}, token=d.get("access_token"))


def _off_set(email, pw, name):
    import secrets
    d = _acc_load()
    salt = secrets.token_hex(16)
    d["offline"] = {"email": email.strip().lower(), "name": name, "salt": salt, "hash": _pw_hash(pw, salt),
                    "last_ok": datetime.date.today().isoformat()}
    _acc_save(d)


def _off_fresh(o):
    try:
        return (datetime.date.today() - datetime.date.fromisoformat(o["last_ok"])).days <= OFFLINE_DAYS
    except Exception:
        return False


def _off_check(email, pw):
    import hmac
    o = _acc_load().get("offline")
    if o and o["email"] == email.strip().lower() and _off_fresh(o) and hmac.compare_digest(_pw_hash(pw, o["salt"]), o["hash"]):
        return {"name": o["name"], "email": o["email"], "status": "ok"}
    return None


class LoginDialog(QDialog):
    """Start screen: the logo in the middle, the sign-in form underneath. First time on a PC it opens on 'Create account'."""

    def __init__(self):
        super().__init__()
        self.user = None
        self.setWindowTitle(APP_NAME)
        self.setWindowIcon(app_icon())
        self.setFixedSize(460, 700)
        self.online = sb_conf() is not None
        self.mode = "login" if (self.online or _acc_load()["users"]) else "register"
        lay = QVBoxLayout(self)
        lay.setContentsMargins(46, 34, 46, 28)
        lay.setSpacing(8)
        mark = QLabel()
        mark.setAlignment(Qt.AlignmentFlag.AlignCenter)
        mark.setPixmap(logo_pixmap().scaledToHeight(120, Qt.TransformationMode.SmoothTransformation))
        lay.addWidget(mark)
        t = QLabel("<span style='font-size:17px;font-weight:700;letter-spacing:2px'>MCP ARCHITECTURE &amp; INTERIORS</span><br>"
                   "<span style='font-size:12px;color:#9aa0a8;letter-spacing:1px'>SANS Compliance Suite</span>")
        t.setAlignment(Qt.AlignmentFlag.AlignCenter)
        lay.addWidget(t)
        lay.addStretch(1)
        self.head = QLabel()
        self.head.setStyleSheet("font-size:15px;font-weight:700;")
        lay.addWidget(self.head)
        self.f_name = QLineEdit(); self.f_name.setPlaceholderText("Your name")
        self.f_email = QLineEdit(); self.f_email.setPlaceholderText("Email address")
        self.f_email.setText(SETTINGS.get("last_email", ""))
        self.f_rec = QLineEdit(); self.f_rec.setPlaceholderText("Recovery key (XXXX-XXXX-XXXX-XXXX)")
        self.f_pw = QLineEdit(); self.f_pw.setPlaceholderText("Password")
        self.f_pw2 = QLineEdit(); self.f_pw2.setPlaceholderText("Repeat password")
        for f_ in (self.f_pw, self.f_pw2):
            f_.setEchoMode(QLineEdit.EchoMode.Password)
        for f_ in (self.f_name, self.f_email, self.f_rec, self.f_pw, self.f_pw2):
            f_.setMinimumHeight(34)
            f_.returnPressed.connect(self.go)
            lay.addWidget(f_)
        self.show_pw = QCheckBox("Show password")
        self.show_pw.toggled.connect(lambda on: [f_.setEchoMode(QLineEdit.EchoMode.Normal if on else QLineEdit.EchoMode.Password) for f_ in (self.f_pw, self.f_pw2)])
        lay.addWidget(self.show_pw)
        self.keep = QCheckBox("Keep me signed in on this PC")
        self.keep.setChecked(True)
        lay.addWidget(self.keep)
        self.err = QLabel("")
        self.err.setWordWrap(True)
        self.err.setStyleSheet("color:#ff8f9c;")
        lay.addWidget(self.err)
        self.btn = QPushButton()
        self.btn.setProperty("accent", True)
        self.btn.setMinimumHeight(42)
        self.btn.clicked.connect(self.go)
        lay.addWidget(self.btn)
        row = QHBoxLayout()
        self.l1 = QPushButton(); self.l2 = QPushButton()
        for b_ in (self.l1, self.l2):
            b_.setFlat(True)
            b_.setCursor(Qt.CursorShape.PointingHandCursor)
            b_.setStyleSheet("QPushButton{background:transparent;border:none;color:#9aa0a8;text-decoration:underline;}"
                             "QPushButton:hover{color:#d8132b;}")
            row.addWidget(b_)
        lay.addLayout(row)
        self.l1.clicked.connect(lambda: self.set_mode("register" if self.mode == "login" else "login"))
        self.l2.clicked.connect(self.l2_click)
        self.set_mode(self.mode)

    def set_mode(self, m):
        self.mode = m
        self.err.setText("")
        self.err.setStyleSheet("color:#ff8f9c;")
        reg, res = m == "register", m == "reset"
        self.head.setText({"login": "Sign in", "register": "Create your account", "reset": "Reset your password",
                           "activate": "Enter your licence key"}.get(m, ""))
        self.f_name.setVisible(reg)
        act = m == "activate"
        self.f_rec.setVisible(res or act)
        self.f_rec.setPlaceholderText("Licence key (MCP-XXXX-XXXX-XXXX)" if (act or reg) and self.online
                                      else "Code from the email" if self.online else "Recovery key (XXXX-XXXX-XXXX-XXXX)")
        self.f_pw.setPlaceholderText("New password (at least 8 characters)" if (reg or res) else "Password")
        self.f_email.setVisible(not act)
        self.f_pw.setVisible(not act)
        self.f_pw2.setVisible(reg or res)
        self.show_pw.setVisible(not act)
        self.keep.setVisible(m == "login")
        self.btn.setText({"login": "Sign in", "register": "Create account", "reset": "Set new password",
                          "activate": "Activate"}.get(m, ""))
        self.l1.setText("Create a new account" if m == "login" else "I already have an account")
        self.l1.setVisible(not act)
        self.l2.setText("Forgot password?" if m == "login" else ("Email me a code" if (res and self.online) else ""))
        self.l2.setVisible(m == "login" or (res and self.online))
        (self.f_rec if act else self.f_email if m != "register" else self.f_name).setFocus()

    def l2_click(self):
        if self.mode == "login":
            self.set_mode("reset")
            return
        em = self.f_email.text().strip()
        if "@" not in em:
            self.err.setText("Enter your email address first.")
            return
        try:
            sb_send_code(em)
            self.err.setStyleSheet("color:#3fbf6b;")
            self.err.setText("A code was sent to that email. Enter it below with your new password.")
        except SbError as ex:
            self.err.setStyleSheet("color:#ff8f9c;")
            self.err.setText(str(ex))

    def _finish_login(self, u, pw, checked=False):
        """Account found: now the licence decides. No key yet -> ask for it."""
        self._u, self._pw = u, pw
        try:
            st = u["status"] if checked else sb_licence(u["token"])
        except SbError as ex:
            self.err.setText(str(ex))
            return
        if st == "none":
            self.set_mode("activate")
            self.err.setStyleSheet("color:#9aa0a8;")
            self.err.setText("This account has no licence yet. Run supabase_user_keys.sql in Supabase, or enter a licence key.")
            return
        if st == "revoked":
            self.err.setText("This licence has been switched off. Contact MCP Architecture & Interiors.")
            return
        if st == "expired":
            self.err.setText("This licence has expired. Contact MCP Architecture & Interiors for a new key.")
            return
        _off_set(u["email"], pw, u["name"])
        SETTINGS["last_email"] = u["email"]
        save_settings()
        if self.keep.isChecked() or self.mode in ("activate", "register"):
            SETTINGS["sb_refresh"] = u["refresh"]
            save_settings()
        self.user = u
        self.accept()

    def go_online(self):
        em, pw = self.f_email.text().strip(), self.f_pw.text()
        self.err.setStyleSheet("color:#ff8f9c;")
        if self.mode == "login":
            try:
                u = sb_login(em, pw)
            except SbError as ex:
                if ex.offline:
                    u = _off_check(em, pw)
                    if u:
                        self.user = u
                        self.accept()
                        return
                    self.err.setText("No internet connection. You can only sign in without internet on a PC "
                                     "that signed in within the last %d days." % OFFLINE_DAYS)
                else:
                    self.err.setText("That email and password do not match." if ex.status in (400, 401, 422) else str(ex))
                return
            self._finish_login(u, pw)
            return
        if self.mode == "activate":
            try:
                st = sb_redeem(self._u["token"], self.f_rec.text())
            except SbError as ex:
                self.err.setText(str(ex))
                return
            self._u["status"] = st
            self._finish_login(self._u, self._pw, checked=True)
            return
        if "@" not in em or "." not in em.split("@")[-1]:
            self.err.setText("Enter a valid email address.")
            return
        if len(pw) < 8:
            self.err.setText("The password needs at least 8 characters.")
            return
        if pw != self.f_pw2.text():
            self.err.setText("The two passwords are not the same.")
            return
        try:
            if self.mode == "register":
                if not self.f_name.text().strip():
                    self.err.setText("Enter your name.")
                    return
                sb_signup(self.f_name.text(), em, pw, new_licence_key())     # the service issues the licence by itself
                try:
                    u = sb_login(em, pw)
                except SbError as ex:
                    if "confirm" in str(ex).lower():                          # the e-mail with the key and a confirm link is on its way
                        QMessageBox.information(self, APP_NAME,
                                                "Your account was created.\n\nWe sent an e-mail with your licence key and a link to "
                                                "confirm your address. Click the link, then sign in here.")
                        self.set_mode("login")
                        return
                    raise
                self._finish_login(u, pw)
            else:
                sb_reset(em, self.f_rec.text(), pw)
                QMessageBox.information(self, APP_NAME, "Your password was changed. Sign in with the new one.")
                self.f_pw.clear(); self.f_pw2.clear()
                self.set_mode("login")
        except SbError as ex:
            self.err.setText(str(ex))

    def go(self):
        if self.online:
            return self.go_online()
        em, pw = self.f_email.text().strip(), self.f_pw.text()
        if self.mode == "login":
            u = acc_check(em, pw)
            if not u:
                self.err.setText("That email and password do not match.")
                return
            if self.keep.isChecked():
                acc_remember(u["email"])
            self.user = u
            self.accept()
            return
        if "@" not in em or "." not in em.split("@")[-1]:
            self.err.setText("Enter a valid email address.")
            return
        if len(pw) < 8:
            self.err.setText("The password needs at least 8 characters.")
            return
        if pw != self.f_pw2.text():
            self.err.setText("The two passwords are not the same.")
            return
        if self.mode == "register":
            if not self.f_name.text().strip():
                self.err.setText("Enter your name.")
                return
            rk, er = acc_register(self.f_name.text(), em, pw)
            if er:
                self.err.setText(er)
                return
            QMessageBox.information(self, APP_NAME,
                                    "Your account is ready.\n\nRECOVERY KEY:   %s\n\nWrite it down and keep it safe. It is the only way to "
                                    "set a new password if you forget this one." % rk)
            self.user = acc_check(em, pw)
            self.accept()
        else:
            if acc_reset(em, self.f_rec.text(), pw):
                QMessageBox.information(self, APP_NAME, "Your password was changed. Sign in with the new one.")
                self.f_pw.clear(); self.f_pw2.clear()
                self.set_mode("login")
            else:
                self.err.setText("The email or the recovery key is not right.")


def _gate_log(msg):
    try:
        with open(os.path.join(tempfile.gettempdir(), "mot_login.log"), "a", encoding="utf-8") as f:
            f.write(datetime.datetime.now().strftime("%d %H:%M:%S ") + str(msg) + "\n")
    except Exception:
        pass


def _off_touch():
    d = _acc_load()
    if d.get("offline"):
        d["offline"]["last_ok"] = datetime.date.today().isoformat()
        _acc_save(d)


def sign_in_gate(app):
    """The person who chose 'Keep me signed in' goes straight in. Only a licence that is really switched off (or a
    refresh that is really refused with no recent successful sign-in on this PC) sends them back to the sign-in screen."""
    if sb_conf():
        rt = SETTINGS.get("sb_refresh", "")
        if rt:
            o = _acc_load().get("offline")
            cached = {"name": o["name"], "email": o["email"], "status": "ok"} if (o and _off_fresh(o)) else None
            try:
                u = sb_refresh(rt)
            except SbError as ex:
                _gate_log("refresh failed (offline=%s status=%s): %s" % (ex.offline, ex.status, ex))
                # the saved session is kept whatever the reason: a refusal can be a one-off (a quick double start
                # uses the single-use token twice). It is only removed when the licence itself is switched off.
                if cached:                                  # no internet, or the token was just used by a quick restart
                    return cached
            else:
                SETTINGS["sb_refresh"] = u["refresh"]       # keep the new token before anything else can go wrong
                save_settings()
                try:
                    st = sb_licence(u["token"])
                except SbError as ex:
                    _gate_log("licence check failed: %s" % ex)
                    st = "ok" if cached else "?"
                _gate_log("kept session, licence: %s" % st)
                if st == "ok":
                    _off_touch()
                    u["status"] = "ok"
                    return u
                if st in ("revoked", "expired"):
                    SETTINGS["sb_refresh"] = ""
                    save_settings()
                elif st == "none" and cached:               # no licence record could be made right now: do not throw them out
                    return cached
        else:
            _gate_log("no saved session")
    else:
        u = acc_remembered()
        if u:
            return u
    app.setStyle("Fusion")
    app.setStyleSheet((light_qss(STUDIO_QSS) if light() else STUDIO_QSS).replace("@TICK@", _tick_png()))
    dlg = LoginDialog()
    if dlg.exec() == QDialog.DialogCode.Accepted:
        return dlg.user
    return None


def main():
    if len(sys.argv) == 3 and sys.argv[1] == "--selftest":
        # Developer check: python mot_light_vent.py --selftest picture.png
        app = QApplication(sys.argv)
        lines, _w, _h = ocr_lines(QImage(sys.argv[2]))
        print(f"OCR OK: {len(lines)} text lines")
        for ln in lines:
            print(ln[4])
        return
    try:                                   # 125% and 150% Windows scaling: use the real factor, do not round it to 100% or 200%
        from PySide6.QtGui import QGuiApplication
        QGuiApplication.setHighDpiScaleFactorRoundingPolicy(Qt.HighDpiScaleFactorRoundingPolicy.PassThrough)
    except Exception:
        pass
    app = QApplication(sys.argv)
    if not any(a in sys.argv for a in ("--restore", "--ready", "--after-update")):   # reloads and updates stay signed in
        user = sign_in_gate(app)
        if not user:
            return
    win = MainWindow()
    apply_glass_theme(app, win)
    app._icon_filter = _IconFilter(app)
    app.installEventFilter(app._icon_filter)
    apply_icons(win)
    wrap_long_labels(win)
    win.setMinimumWidth(0)
    try:
        _av = app.primaryScreen().availableGeometry()
        win.resize(min(1280, _av.width() - 40), min(780, _av.height() - 60))
    except Exception:
        win.resize(1280, 780)
    av = sys.argv[1:]
    restoring = "--restore" in av or "--after-update" in av
    if "--ready" in av:
        win.setWindowOpacity(0.0)            # a reload: stay invisible until the window is fully built and in place
    if "--after-update" in av:                  # started by the installer after an in-program update: put the work back
        _rp = os.path.join(tempfile.gettempdir(), "mot_lv_restore.json")
        if os.path.exists(_rp):
            win.restore_from(_rp)
        else:
            restoring = False
    elif restoring:
        win.restore_from(av[av.index("--restore") + 1])
    if "--geom" in av:
        try:
            x, y, w, h, mx = [int(v) for v in av[av.index("--geom") + 1].split(",")]
            win.setGeometry(x, y, w, h)
            if mx:
                win.showMaximized()
        except Exception:
            pass
    win.show()
    if "--ready" in av:
        try:
            flagp = av[av.index("--ready") + 1]

            def _reveal():
                try:
                    app.processEvents()
                    win.raise_()
                    win.activateWindow()
                finally:
                    win.setWindowOpacity(1.0)
                QTimer.singleShot(120, lambda: open(flagp, "w").close())   # only now does the old window close
            QTimer.singleShot(250, _reveal)
        except Exception:
            win.setWindowOpacity(1.0)
    win.start_autosave()
    if "--ready" not in av:
        QTimer.singleShot(2500, win.maybe_whats_new)
    _openf, _skip = None, False
    for _a in av:                                   # a project file double-clicked in Windows arrives as the argument
        if _skip:
            _skip = False
        elif _a in ("--restore", "--geom", "--ready"):
            _skip = True
        elif not _a.startswith("--") and _a.lower().endswith((".mcplv", ".json")) and os.path.isfile(_a):
            _openf = os.path.abspath(_a)
            break
    if _openf and not restoring:
        QTimer.singleShot(250, lambda: win.open_project_path(_openf))
    elif not restoring:
        QTimer.singleShot(250, lambda: win.check_recovery() or win.start_on_launch())   # step 1: create the project
    sys.exit(app.exec())


if __name__ == "__main__":
    main()
